            b"            cancel.cancel();\n",
            b"        }\n",
            b"        if let Some(h) = self.rate_handle.take() {\n",
            b"            let _ = h.await;\n",
            b"        }\n",
            b"        for (_, (cancel, handle)) in self.listeners.drain() {\n",
            b"            cancel.cancel();\n",
            b"            let _ = handle.await;\n",
            b"        }\n",
            b"        for (_, entry) in self.peers.drain() {\n",
            b"            entry.cancel.cancel();\n",
            b"            // The reconnect loop may sit inside a live connection: abort, then join.\n",
